using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns information about a button of type inlineKeyboardButtonTypeLoginUrl. The method needs to be called when the user presses the button
    /// </summary>
    public Task<TdLib.TdApi.Objects.LoginUrlInfo> GetLoginUrlInfoAsync(long chatId = default, long messageId = default, long buttonId = default)
    {

           using var activity =  StartCallActivity("GetLoginUrlInfoAsync", typeof(GetLoginUrlInfo).FullName ?? "GetLoginUrlInfoAsync");

           try
           {
             return client.GetLoginUrlInfoAsync(chatId, messageId, buttonId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
